) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国家/地区 | CountryArea（v1/countryArea/list）（原 country_areas）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `venue` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
