  `longitude` DECIMAL(10,7) COMMENT '经度 | Venue.longitude',
  `parking` TEXT COMMENT '停车信息 | Venue.parking',
  `phones` VARCHAR(512) COMMENT '联系电话 | Venue.phones',
  `transportation` TEXT COMMENT '交通信息 | Venue.transportation',
