  KEY `idx_venue_city_id` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='场馆 | Venue + Flutter VenueSummary（v1/venues/{id}）（原 venues）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `activity_category` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
