  `type` VARCHAR(64) COMMENT '类型 | PnConfig.type',
  `value` VARCHAR(256) COMMENT '值 | PnConfig.value',
  `dacu` VARCHAR(256) COMMENT '大促标记 | PnConfig.dacu',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_activity_category_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='演出一级分类 | ShowCategory / PnConfig.CategoriesBean（v2/config/categories）（原 activity_categories）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `activity_sub_tag` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sub_tag_id` BIGINT UNSIGNED NOT NULL COMMENT '标签ID | SubCategoryTag.id',
