  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_activity_sub_tag_sub_tag_id` (`sub_tag_id`),
  KEY `idx_activity_sub_tag_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='演出二级标签 | SubCategoryTag / SubCategoryTagsBean（原 activity_sub_tags）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `app_config` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `config_id` BIGINT UNSIGNED NOT NULL COMMENT '配置ID | PnConfig.id',
