  `img_ssl_domain` VARCHAR(256) COMMENT '图片 HTTPS 域名 | PnConfig.imgSslDomain',
  `is_time_to_dacu` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否大促期 | PnConfig.isTimeToDacu',
  `is_sms_captcha_on` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启短信验证码 | PnConfig.smsCaptchaOn',
  `ticket_enough_count` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '票量充足阈值 | PnConfig.ticketEnoughCount',
  `launch_screen` VARCHAR(1024) COMMENT '启动屏 | PnConfig.launchScreen',
  `payment_types` JSON COMMENT '支付方式列表 | PnConfig.paymentTypes',
