  `install_url` VARCHAR(1024) COMMENT '安装地址 | UpdateInfo.installUrl',
  `is_force_update` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否强制更新 | UpdateInfo.isForceUpdate',
  `is_ignorable` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可忽略 | UpdateInfo.isIgnorable',
  `tips_interval_days` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '提示间隔天数 | UpdateInfo.tipsIntervalDays',
  `type` VARCHAR(64) COMMENT '类型 | UpdateInfo.type',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_version_version_code` (`version_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='版本更新 | UpdateInfo（GET apps/latest/{id} · v2/apkTool/latest）（原 app_versions）' ROW_FORMAT=DYNAMIC;

