  `link_type` VARCHAR(64) COMMENT '链接类型 | ActivityBean.linkType',
  `type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 | ActivityBean.type',
  `type_desc` VARCHAR(256) COMMENT '类型描述 | ActivityBean.typeDesc',
  `actor_id` BIGINT UNSIGNED COMMENT '艺人ID | ActivityBean.actorId',
  `venue_id` BIGINT UNSIGNED COMMENT '场馆ID | ActivityBean.venueId',
  `venue_name` VARCHAR(256) COMMENT '场馆名 | ActivityBean.venueName',
  `venue_city_id` BIGINT UNSIGNED COMMENT '场馆城市ID | ActivityBean.venueCityId',
  `city_id` BIGINT UNSIGNED NOT NULL COMMENT '城市ID | ActivityBean.cityId',
  `city_name` VARCHAR(128) COMMENT '城市名 | ActivityBean.cityName',
  `shop_id` BIGINT UNSIGNED COMMENT '店铺ID | ActivityBean.shopId',
  `description` TEXT COMMENT '描述 | ActivityBean.desc',
  `poster` VARCHAR(1024) COMMENT '海报 | ActivityBean.poster',
  `img` VARCHAR(1024) COMMENT '图片 | ActivityBean.img',
  `promo_img` VARCHAR(1024) COMMENT '推广图 | ActivityBean.promoImg',
  `tag_image` VARCHAR(1024) COMMENT '角标图 | ActivityBean.tagImage',
  `area_image` VARCHAR(1024) COMMENT '区域图 | ActivityBean.areaImage',
  `icon` VARCHAR(1024) COMMENT '图标 | ActivityBean.icon',
  `video` VARCHAR(1024) COMMENT '视频 | ActivityBean.video',
  `start_time` DATETIME COMMENT '开始时间 | ActivityBean.start',
  `end_time` DATETIME COMMENT '结束时间 | ActivityBean.end',
  `open_time` DATETIME COMMENT '开售时间 | ActivityBean.openTime',
  `start_sell_time` DATETIME COMMENT '开卖时间 | ActivityBean.startSellTime',
  `time_range` VARCHAR(256) COMMENT '时间文案 | ActivityBean.timeRange',
  `duration` VARCHAR(128) COMMENT '时长 | ActivityBean.duration',
  `year` VARCHAR(16) COMMENT '年份 | ActivityBean.year',
  `distance` VARCHAR(64) COMMENT '距离 | ActivityBean.distance',
  `low_price` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '最低价 | ActivityBean.lowPrice',
  `high_price` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '最高价 | ActivityBean.highPrice',
  `discount_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额 | ActivityBean.discountAmount',
  `discount_rate` DECIMAL(10,4) DEFAULT 0.0000 COMMENT '折扣率 | ActivityBean.discountRate',
  `privilege_discount_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '会员优惠金额 | ActivityBean.privilegeDiscountAmount',
  `rank_weight` DECIMAL(12,4) COMMENT '排序权重 | ActivityBean.rank',
  `star` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '星级 | ActivityBean.star',
  `review_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数 | ActivityBean.reviewNum',
  `want_watch_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '想看数 | ActivityBean.wantWatchNum',
  `total_order_count` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '总订单数 | ActivityBean.totalOrderCount',
  `activity_event_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '场次数 | ActivityBean.activityEventNum',
  `activity_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动数 | ActivityBean.activityNum',
  `favor_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏类型 | ActivityBean.favorType',
  `status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 | ActivityBean.status',
  `publish_status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '发布状态 | ActivityBean.publishStatus',
  `is_searchable` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可搜索 | ActivityBean.searchable',
  `is_sold_out` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否售罄 | ActivityBean.soldOut',
  `is_normal_sold_out` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '普通票售罄 | ActivityBean.normalSoldOut',
  `is_has_seat` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有座 | ActivityBean.hasSeat',
  `area_ticket_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '区域票类型 | ActivityBean.areaTicketType',
  `is_activity_seat_map_opened` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '选座图是否开放 | ActivityBean.activitySeatMapOpened',
  `is_b2c_opened` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'B2C 是否开放 | ActivityBean.b2cOpened',
  `is_credit_pay` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否支持信用付 | ActivityBean.creditPay',
  `is_can_buy_ecard` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可买电子卡 | ActivityBean.canBuyEcard',
  `is_can_review` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可评论 | ActivityBean.canReview',
  `is_direct_buy_official` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '官方直购 | ActivityBean.directBuyOfficial',
  `is_seat_buy_official` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '官方选座 | ActivityBean.seatBuyOfficial',
  `is_general_agency` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '总代 | ActivityBean.generalAgency',
  `is_proxy_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '支持代抢 | ActivityBean.proxyBuy',
  `is_only_proxy_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '仅代抢 | ActivityBean.onlyProxyBuy',
  `is_support_direct_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '支持直购 | ActivityBean.supportDirectBuy',
  `is_support_proxy_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '支持代抢 | ActivityBean.supportProxyBuy',
  `is_group_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '支持拼团 | ActivityBean.groupBuy',
  `is_ultra_low_group` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '超低价拼团 | ActivityBean.ultraLowGroup',
  `is_best_discount` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '最优折扣 | ActivityBean.isBestDiscount',
  `is_need_speed_pack_buy` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '需加速包 | ActivityBean.needSpeedPackBuy',
  `is_no_ticket_compensate_switch` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '无票赔付开关 | ActivityBean.noTicketCompensateSwitch',
  `is_non_refundable_exchangeable` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '不可退可换 | ActivityBean.nonRefundableExchangeable',
  `is_discontinued_ticket_notice` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '停售通知 | ActivityBean.discontinuedTicketNotice',
  `is_pay_after_use_switch` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '先用后付开关 | ActivityBean.payAfterUseSwitch',
  `is_service_charge_open` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费开关 | ActivityBean.serviceChargeOpen',
  `is_show_start_remind` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '开演提醒 | ActivityBean.showStartRemind',
  `is_speed_express` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '极速配送 | ActivityBean.speedExpress',
  `is_wuyou_transfer_supported` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '无忧转票 | ActivityBean.wuyouTransferSupported',
  `price_guarantee_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '保价类型 | ActivityBean.priceGuaranteeType',
  `postage_tip` VARCHAR(512) COMMENT '运费提示 | ActivityBean.postageTip',
  `pre_sale_tip` VARCHAR(512) COMMENT '预售提示 | ActivityBean.preSaleTip',
  `jump_schema` VARCHAR(1024) COMMENT '跳转 scheme | ActivityBean.schema',
  `num_max` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '单笔最大购买数 | ActivityBean.numMax',
  `num_min` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '单笔最小购买数 | ActivityBean.numMin',
  `order_limit` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '限购 | ActivityBean.orderLimit',
  `tour_name` VARCHAR(256) COMMENT '巡演名 | ActivityBean.tourName',
  `venue` JSON COMMENT '场馆快照（原 Venue） | ActivityBean.venue',
  `actors` JSON COMMENT '艺人列表（原 List<ActorBean>） | ActivityBean.actors',
  `actor_info` JSON COMMENT '艺人二维码（原 ActorQrBean） | ActivityBean.actorInfo',
  `activity_details` JSON COMMENT '详情列表（原 List<ActivityDetail>） | ActivityBean.activityDetails',
  `activity_lineup` JSON COMMENT '阵容（原 List<ActivityLineupBean>） | ActivityBean.activityLineup',
  `activity_linked_groups` JSON COMMENT '关联群组（原 List<ActivityGroupBean>） | ActivityBean.activityLinkedGroups',
  `activity_purchase_info` JSON COMMENT '购买信息（内部类） | ActivityBean.activityPurchaseInfo',
  `activity_refund_policy` JSON COMMENT '退票政策（原 ActivityRefundPolicyBean） | ActivityBean.activityRefundPolicy',
  `campaigns` JSON COMMENT '活动列表（原 List<ActivityCampaign>） | ActivityBean.campaigns',
  `choose_ticket_calendar_data` JSON COMMENT '选票日历（原 ChooseTicketCalendarData） | ActivityBean.chooseTicketCalendarData',
  `display_tags` JSON COMMENT '展示标签（内部类 ActivityDisplayTag） | ActivityBean.displayTags',
  `enter_tip` JSON COMMENT '入场提示（原 ShowTip） | ActivityBean.enterTip',
  `events` JSON COMMENT '场次列表（原 List<ActivityEventBean>） | ActivityBean.events',
  `has_ticket_events` JSON COMMENT '有票场次 | ActivityBean.hasTicketEvents',
  `order_num_limit` JSON COMMENT '限购（内部类 OrderNumLimitBean） | ActivityBean.orderNumLimit',
  `pin_tuan_info` JSON COMMENT '拼团信息（原 PinTuanInfo） | ActivityBean.pinTuanInfo',
  `proxy_buy_info` JSON COMMENT '代抢信息（原 ProxyBuyInfo） | ActivityBean.proxyBuyInfo',
  `ticket_categories` JSON COMMENT '票档（原 List<TicketCategory>） | ActivityBean.ticketCategories',
  `ticket_tip` JSON COMMENT '购票提示（原 ShowTip） | ActivityBean.ticketTip',
  `tour` JSON COMMENT '巡演（内部类 TourBean） | ActivityBean.tour',
  `activities` JSON COMMENT '关联演出（原 List<ActivityBean>） | ActivityBean.activities',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_activity_activity_id` (`activity_id`),
  KEY `idx_activity_city_id` (`city_id`),
  KEY `idx_activity_category_id` (`category_id`),
  KEY `idx_activity_venue_id` (`venue_id`),
  KEY `idx_activity_start_time` (`start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='演出主档 | ActivityBean（100+ 顶层字段，含 4 个内部类；DTO 字段全量落列）（原 activities）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `activity_event` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `activity_event_id` BIGINT UNSIGNED NOT NULL COMMENT '场次ID | ActivityEventBean.id',
  `activity_id` BIGINT UNSIGNED NOT NULL COMMENT '演出ID | ActivityEventBean.activityId',
  `start_time` DATETIME COMMENT '开演时间 | ActivityEventBean.start',
  `end_time` DATETIME COMMENT '结束时间 | ActivityEventBean.end',
  `time_range` VARCHAR(256) COMMENT '时间文案 | Test.timeRange',
  `specification` VARCHAR(256) COMMENT '规格 | ActivityEventBean.specification',
  `description` TEXT COMMENT '描述 | ActivityEventBean.desc',
  `low_price` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '最低价 | ActivityEventBean.lowPrice',
  `discount_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额 | ActivityEventBean.discountAmount',
  `discount_rate` DECIMAL(10,4) DEFAULT 0.0000 COMMENT '折扣率 | ActivityEventBean.discountRate',
  `is_discount` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有折扣 | ActivityEventBean.discountFlag',
  `is_price_lowest` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否最低价 | ActivityEventBean.priceLowest',
  `is_has_ticket` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有票 | ActivityEventBean.hasTicket',
  `tickets_number` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '票数量 | ActivityEventBean.ticketsNumber',
  `tickets_flag` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '票标记 | ActivityEventBean.ticketsFlag',
  `is_seat_map` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否选座图 | ActivityEventBean.seatMapFlag',
  `seat_tickets_size` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '座位票数 | ActivityEventBean.seatTicketsSize',
  `ticket_group_id` BIGINT UNSIGNED COMMENT '票组ID | ActivityEventBean.ticketGroupId',
  `status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（2=停售，见 dict_enum.SaleStatus） | ActivityEventBean.status',
  `venue_id` BIGINT UNSIGNED COMMENT '场馆ID（Test 补充） | Test.venueId',
  `venue_name` VARCHAR(256) COMMENT '场馆名（Test 补充） | Test.venueName',
  `available_numbers` JSON COMMENT '可选数量（原 List<Integer>） | ActivityEventBean.availableNumbers',
