-- ========================================================================
--  sql · 05_order.sql（S2 全量规范重构版）
--  规范: 单数表名 / id BIGINT UNSIGNED 自增 / gmt_create,gmt_modified DATETIME
--        is_xxx TINYINT UNSIGNED / 金额 DECIMAL / 无物理外键 / 无冗余索引
--  表: order_info, order_event, order_item, order_good, order_goods_package, order_delivery, order_confirm_snapshot, order_postage, order_comment, speed_pack
-- ========================================================================

USE `planstar_order`;

-- ----------------------------------------------------------------------
--  域 4 · 交易与支付（order / payment / refund）
-- ----------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `order_info` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_id` BIGINT UNSIGNED NOT NULL COMMENT '订单ID | unifiedOrder.orderId',
  `order_number` VARCHAR(64) NOT NULL COMMENT '订单号 | Flutter OrderNumber.value',
  `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户ID | 推断',
  `activity_id` BIGINT UNSIGNED COMMENT '演出ID | 推断',
  `activity_event_id` BIGINT UNSIGNED COMMENT '场次ID | 推断',
  `shop_id` BIGINT UNSIGNED COMMENT '店铺ID | 推断',
  `business_order_id` BIGINT UNSIGNED COMMENT '业务订单ID | OrderItem.businessOrderId',
  `business_order_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务订单类型 | OrderItem.businessOrderType',
  `order_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单类型（1 普通票 / 2 拼团 / 5 抢票 / 60 Plus会员 / 70 加速包，见 dict_enum.OrderType） | MakeOrderRequestBody.orderType',
  `subject_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付主体类型（9 普通 / 6 会员充值 / 2 拼团 / 60 Plus，见 dict_enum.SubjectType） | gotoPayActivity 硬编码',
  `status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单状态（见 dict_enum.OrderStatus） | OrderEvent.currentStatus',
  `order_status_desc` VARCHAR(256) COMMENT '状态文案 | OrderItem.orderStatusDesc',
  `order_type_desc` VARCHAR(256) COMMENT '类型文案 | OrderItem.orderTypeDesc',
  `order_type_desc_rgb` VARCHAR(64) COMMENT '类型文案色值 | OrderItem.orderTypeDescRGB',
  `title` VARCHAR(512) COMMENT '标题 | OrderItem.title',
  `poster` VARCHAR(1024) COMMENT '海报 | OrderItem.poster',
  `order_amount_desc` VARCHAR(256) COMMENT '金额文案 | OrderItem.orderAmountDesc',
  `descs` JSON COMMENT '描述行（原 List<String>） | OrderItem.descs',
  `spec` JSON COMMENT '规格（原 List<Spec>） | OrderItem.spec',
  `buttons` JSON COMMENT '操作按钮（原 List<OrderButtonBean>） | OrderItem.buttons',
  `pay_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '实付金额 | MakeOrderRequestBody.payAmount',
  `total_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '订单总额 | MakeOrderRequestBody.totalAmount',
  `good_total_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '商品总额 | OrderConfirmInfo.goodTotalAmount',
  `postage` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '运费 | MakeOrderRequestBody.postage',
  `discount_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额 | 推断',
  `split_order_fee` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '拆单费 | BizParam.splitOrderContext.splitOrderFee',
  `consume_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '消费金额 | MakeOrderRequestBody.consumeAmount',
  `coupon_ids` JSON COMMENT '使用的券ID（与 campaignIds 互斥） | MakeOrderRequestBody.couponIds',
  `campaign_ids` JSON COMMENT '使用的活动ID（与 couponIds 互斥） | MakeOrderRequestBody.campaignIds',
  `gift_cards` JSON COMMENT '使用的礼品卡（原 List<GiftCard>） | MakeOrderRequestBody.giftCards',
  `goods` JSON COMMENT '商品（原 List<Goods>） | MakeOrderRequestBody.goods',
  `deliver` JSON COMMENT '配送（原 Deliver） | MakeOrderRequestBody.deliver',
  `additions` JSON COMMENT '附加项（原 List<? extends JSONObject>） | MakeOrderRequestBody.additions',
  `real_name_info_ids` JSON COMMENT '实名信息ID（原 List<Integer>） | MakeOrderRequestBody.realNameInfoIds',
  `biz_param` JSON COMMENT '业务参数（原 BizParam） | MakeOrderRequestBody.bizParam',
  `confirm_snapshot` JSON COMMENT '确认页快照（原 ConfirmSnapshot） | MakeOrderRequestBody.confirmSnapshot',
  `channel_attribute_info` TEXT COMMENT '渠道归因（自嵌套 JSON 字符串） | MakeOrderRequestBody.channelAttributeInfo',
  `id_card` VARCHAR(128) COMMENT '证件号 | MakeOrderRequestBody.idCard',
  `id_card_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '证件类型 | MakeOrderRequestBody.idCardType',
  `name` VARCHAR(128) COMMENT '收件人 | MakeOrderRequestBody.name',
  `phone` VARCHAR(64) COMMENT '联系电话 | MakeOrderRequestBody.phone',
  `user_address_id` BIGINT UNSIGNED COMMENT '地址ID | MakeOrderRequestBody.userAddressId',
  `is_continuous_seat` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否连座 | MakeOrderRequestBody.isContinuousSeat',
  `price_guarantee_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '保价类型 | MakeOrderRequestBody.priceGuaranteeType',
  `pin_tuan_id` BIGINT UNSIGNED COMMENT '拼团ID | MakeOrderRequestBody.pinTuanId',
  `balance_speed_pack` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '加速包余额部分 | MakeOrderRequestBody.balanceSpeedPack',
  `cash_speed_pack` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '加速包现金部分 | MakeOrderRequestBody.cashSpeedPack',
  `channel` VARCHAR(128) COMMENT '渠道 | BizParam.channel',
  `is_pay_after_use` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '先用后付 | PayAfterUseInfo.check',
  `is_credit_pay` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '信用付 | CreditPay',
  `success_page` VARCHAR(1024) COMMENT '支付成功跳转 | PayInfo.successPage',
  `fail_page` VARCHAR(1024) COMMENT '支付失败跳转 | PayInfo.failPage',
  `refund_amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '已退金额 | 推断',
  `pay_time` DATETIME COMMENT '支付时间 | 推断',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_info_order_id` (`order_id`),
  UNIQUE KEY `uk_order_info_order_number` (`order_number`),
  KEY `idx_order_info_user_id_status` (`user_id`,`status`),
  KEY `idx_order_info_activity_id` (`activity_id`),
  KEY `idx_order_info_gmt_create` (`gmt_create`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一订单 | unifiedOrder · OrderItem · MakeOrderRequestBody · OrderEvent（原 orders）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `order_event` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_event_id` BIGINT UNSIGNED NOT NULL COMMENT '事件ID | OrderEvent.id',
  `order_id` BIGINT UNSIGNED NOT NULL COMMENT '订单ID | OrderEvent.orderId',
  `origin_status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '原状态 | OrderEvent.originStatus',
  `current_status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '新状态 | OrderEvent.currentStatus',
  `operator_id` BIGINT UNSIGNED COMMENT '操作人 | OrderEvent.operatorId',
  `operator_type` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人类型 | OrderEvent.operatorType',
  `supplement` TEXT COMMENT '补充说明 | OrderEvent.supplement',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_event_order_event_id` (`order_event_id`),
  KEY `idx_order_event_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单状态流转事件 | OrderEvent（v1/unifiedOrder/{orderId}/status）（原 order_events）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `order_item` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '代理主键',
  `order_id` BIGINT UNSIGNED NOT NULL COMMENT '订单ID | OrderItem.orderId',
  `business_order_id` BIGINT UNSIGNED COMMENT '业务订单ID | OrderItem.businessOrderId',
