CREATE TABLE IF NOT EXISTS `speed_pack` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '代理主键',
  `user_id` BIGINT UNSIGNED COMMENT '用户ID | 推断',
  `order_id` BIGINT UNSIGNED COMMENT '订单ID | 推断',
  `amount` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '加速包金额 | SpeedPackChoice.amount',
  `description` VARCHAR(512) COMMENT '描述 | SpeedPackChoice.desc',
  `is_recommend` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐 | SpeedPackChoice.recommend',
  `success_rate` DECIMAL(10,4) DEFAULT 0.0000 COMMENT '成功率 | SpeedPackChoice.successRate',
  `speed_pack_balance` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '加速包余额 | BizParam.speedPackBalance',
  `balance_speed_pack` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '余额抵扣部分 | MakeOrderRequestBody.balanceSpeedPack',
  `cash_speed_pack` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '现金部分 | MakeOrderRequestBody.cashSpeedPack',
