  `split_order_desc` VARCHAR(1024) COMMENT '拆单说明 | SplitOrderContext.splitOrderDesc',
  `split_order_fee` DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '拆单费 | SplitOrderContext.splitOrderFee',
