-- ========================================================================
--  sql · 08_community.sql（S2 全量规范重构版）
--  规范: 单数表名 / id BIGINT UNSIGNED 自增 / gmt_create,gmt_modified DATETIME
--        is_xxx TINYINT UNSIGNED / 金额 DECIMAL / 无物理外键 / 无冗余索引
--  表: review, review_reply, review_todo, feed, feed_media, topic, community, user_article, like_record, video_channel
-- ========================================================================

USE `planstar_community`;

-- ----------------------------------------------------------------------
--  域 6 · 内容与社区（UGC / feed / content）
-- ----------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `review` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `review_id` BIGINT UNSIGNED NOT NULL COMMENT '评论ID | Review.id',
  `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户ID | Review.userId',
  `activity_id` BIGINT UNSIGNED NOT NULL COMMENT '演出ID | Review.activityId',
  `content` TEXT COMMENT '内容 | Review.content',
  `rating` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '星级 | Review.rank / CreateReviewRequestBody.rank',
  `images` JSON COMMENT '图片（原 List<String>） | Review.images',
  `videos` JSON COMMENT '视频（原 List<JSONObject> / JSONArray） | Review.videos',
  `is_liked` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已赞 | Review.liked',
  `likes` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '赞数 | Review.likes',
  `reply_count` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '回复数 | Review.replyCount',
  `status` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 | Review.status',
  `num_plus_related` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '相关数 | Review.numPlusRelated',
  `page_index` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '页码（DTO 复用） | Review.pageIndex',
  `page_size` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '页大小（DTO 复用） | Review.pageSize',
  `total_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '总数（DTO 复用） | Review.totalNum',
  `data` JSON COMMENT '自嵌套列表（原 List<Review>） | Review.data',
  `activity` JSON COMMENT '演出快照 | Review.activity',
  `user` JSON COMMENT '用户快照 | Review.user',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_review_id` (`review_id`),
  KEY `idx_review_activity_id` (`activity_id`),
  KEY `idx_review_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评论 / 评价 | Review / CreateReviewRequestBody（v1/reviews · v3/reviews）（原 reviews）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `review_reply` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `reply_id` BIGINT UNSIGNED NOT NULL COMMENT '回复ID | Reply.id',
  `review_id` BIGINT UNSIGNED NOT NULL COMMENT '评论ID | Reply.reviewId',
