  `content` TEXT COMMENT '内容 | Reply.content',
  `is_top` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否置顶 | Reply.isTop',
  `page_index` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '页码 | Reply.pageIndex',
  `page_size` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '页大小 | Reply.pageSize',
  `total_num` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '总数 | Reply.totalNum',
  `data` JSON COMMENT '自嵌套列表（原 List<Reply>） | Reply.data',
  `user` JSON COMMENT '用户快照 | Reply.user',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_reply_reply_id` (`reply_id`),
  KEY `idx_review_reply_review_id` (`review_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评论回复 | Reply / ReplySendRequestBody（v1/reviews/{id}/replies）（原 review_replies）' ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `review_todo` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `todo_id` BIGINT UNSIGNED NOT NULL COMMENT 'ID | ReviewToDo.id',
  `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户ID | ReviewToDo.userId',
