  `code` INT NOT NULL DEFAULT 0 COMMENT '服务端 wire code（字符串枚举按序号）',
  `description` VARCHAR(512) NOT NULL COMMENT '中文含义 / 备注',
  `source` VARCHAR(512) NOT NULL COMMENT '证据来源（文件:行号）',
  `gmt_create` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dict_enum_enum_name_constant_name` (`enum_name`,`constant_name`),
  UNIQUE KEY `uk_dict_enum_enum_name_code` (`enum_name`,`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='全量枚举字典：Android 18 枚举 + Flutter 枚举 + 编译期常量（原 dict_enums）' ROW_FORMAT=DYNAMIC;

